import unittest, io
seen = []
real = SUITE_TEST.test_morning.__globals__['greeting']
def spy(name, now=None):
    if now is not None:
        seen.append(now.hour)
    return real(name, now)
SUITE_TEST.test_morning.__globals__['greeting'] = spy
result = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(unittest.TestLoader().loadTestsFromTestCase(SUITE_TEST))
assert result.wasSuccessful(), 'greeting tests failed'
bands = {'morning' if h < 12 else 'afternoon' if h < 18 else 'evening' for h in seen}
assert {'morning', 'afternoon', 'evening'} <= bands, 'test all three bands with injected times'
